css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .66); position: relative; }
.loader .field { position: absolute; left: 0; right: 0; bottom: 10%; height: 6%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 35%, transparent); }
.loader i { position: absolute; bottom: 17%; width: 2%; height: 8%; border-radius: 2px; background: color-mix(in srgb, var(--accent) 50%, transparent); }
.loader i:nth-of-type(1) { left: 34%; }
.loader i:nth-of-type(2) { left: 58%; }
.loader i:nth-of-type(3) { left: 82%; }
.loader .spear { position: absolute; left: 4%; bottom: 22%; width: 34%; height: 4%; border-radius: 2px; background: linear-gradient(90deg, var(--accent-2), var(--accent)); animation: jav-throw calc(var(--loader-speed) * 2.2) cubic-bezier(.35, .05, .55, 1) infinite; }
@keyframes jav-throw { 0% { opacity: 0; transform: translate(0, 0) rotate(-32deg); } 10% { opacity: 1; } 50% { transform: translate(96%, -170%) rotate(-4deg); } 88% { opacity: 1; transform: translate(190%, 4%) rotate(54deg); } 100% { opacity: 0; transform: translate(190%, 4%) rotate(54deg); } }
